import sys,json
from pathlib import Path
import jax
import jax.numpy as jnp
import numpy as np
if "phydrax" in sys.modules: raise RuntimeError("Core imported before standalone plugin probe")
@jax.jit
def gradient(indices: jax.Array) -> jax.Array:
    dims=jax.lax.ScatterDimensionNumbers(update_window_dims=(0,),inserted_window_dims=(),scatter_dims_to_operand_dims=(0,))
    return jax.grad(lambda update:jnp.sum(jax.lax.scatter_add(jnp.zeros(5,dtype=jnp.float32),indices,update,dims,unique_indices=True,mode="drop")))(jnp.ones(2,dtype=jnp.float32))
result=gradient(jnp.asarray([2**32],dtype=jnp.int64));result.block_until_ready()
np.testing.assert_array_equal(np.asarray(result),np.zeros(2,dtype=np.float32))
standalone="phydrax" not in sys.modules
import phydrax
from phydrax.backends import metal_environment
report=metal_environment()
if not report.successful or not report.facts.device_probed:raise RuntimeError(str(report.issues))
if not Path(phydrax.__file__).resolve().is_relative_to(Path(sys.prefix).resolve()):raise RuntimeError("Checkout imported")
print(json.dumps({"standalone_no_core_import":standalone,"gradient":np.asarray(result).tolist(),"platform":jax.default_backend(),"runtime":jax.devices()[0].client.platform_version,"source_id":report.facts.source_id,"core":phydrax.__file__}))
